-- OPTIONAL cosmetic/reporting cleanup of exact source fallback rows.
-- All 10934 IDs matched ItemSet.dbc and item_template in the supplied snapshot.
-- 10934 safe subset: item_template.InventoryType equals Item.dbc.InventoryType.
-- Excludes 0 DB/DBC inventory mismatches and 0 unresolved records.
-- Runtime fallback already fills these names IN MEMORY; this merely persists them,
-- reducing recurring log noise (and repeated fallback lookup).
-- It does NOT solve the separate 836 item-set parts without item_template.
-- Re-runnable; never overwrites existing names. `VerifiedBuild` intentionally NULL.
DROP TEMPORARY TABLE IF EXISTS `coa_safe_itemset_fallback_ids`;
CREATE TEMPORARY TABLE `coa_safe_itemset_fallback_ids`
  (`entry` INT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=InnoDB;













































SELECT `t`.`entry`, `t`.`name`,`t`.`InventoryType`,NULL
FROM `coa_safe_itemset_fallback_ids` AS `q`
JOIN `item_template` AS `t` ON `t`.`entry`=`q`.`entry`
LEFT JOIN `item_set_names` AS `n` ON `n`.`entry`=`q`.`entry`
WHERE `n`.`entry` IS NULL;

DROP TEMPORARY TABLE IF EXISTS `coa_safe_itemset_fallback_ids`;
